function cloudLoginDialog(){
 modal('登录个人账户',`<form id="cloud-login-form"><label>用户名<input name="username" autocomplete="username" maxlength="100" required></label><label>密码<input name="password" type="password" autocomplete="current-password" required></label><p class="footnote">登录后打开该用户的本机账本。原本地账本会保留；云同步连接后会自动交换记录；原本地账本迁移需要你明确选择。</p><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">登录</button></div></form>`);
 const form=$<HTMLFormElement>('#cloud-login-form');form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const v=formData(form);try{const identity=await cloudbaseSignIn(v.username,v.password);await selectLocalLedger(identity.uid);rememberCloudIdentity(identity);try{await prepareCloudLedger(identity,v.password);await synchronizeCloud();await refresh();close();toast('已登录，账本已同步');}catch(e){await refresh();close();error(e);}}finally{form.querySelector<HTMLInputElement>('[name=password]')!.value='';}});};
}
async function cloudLogout(){await cloudbaseSignOut();await selectLocalLedger(null);rememberCloudIdentity(null);location.reload();}
function periodDialog(){
 const current=selectedPeriod();modal('选择日期范围',`<form id="period-form"><label>查看范围<select name="mode">${opts([['MONTH','月份'],['YEAR','年份'],['WEEK','一周'],['QUARTER','近三个月'],['CUSTOM','自定义日期']],rangeMode)}</select></label><label id="period-month-field">月份<input name="month" type="month" value="${month}"></label><label id="period-year-field">年份<input name="year" type="number" min="1900" max="9998" value="${rangeAnchor.slice(0,4)}"></label><label id="period-week-field">这一周中的日期<input name="anchor" type="date" value="${rangeAnchor}"></label><div id="period-custom-fields" class="form-grid"><label>开始日期<input name="start" type="date" value="${current.start}"></label><label>结束日期<input name="end" type="date" value="${current.end}"></label></div><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">查看</button></div></form>`);
 const form=$<HTMLFormElement>('#period-form'),update=()=>{const mode=formData(form).mode;$('#period-month-field').hidden=!['MONTH','QUARTER'].includes(mode);$('#period-year-field').hidden=mode!=='YEAR';$('#period-week-field').hidden=mode!=='WEEK';$('#period-custom-fields').hidden=mode!=='CUSTOM';};form.querySelector<HTMLSelectElement>('[name=mode]')!.onchange=update;update();
 form.onsubmit=e=>{e.preventDefault();const v=formData(form),mode=v.mode as PeriodMode,anchor=mode==='YEAR'?v.year+'-01-01':['MONTH','QUARTER'].includes(mode)?v.month+'-01':v.anchor;try{const range=selectPeriod(mode,anchor,{start:v.start,end:v.end});rangeMode=mode;rangeAnchor=anchor;month=anchor.slice(0,7);customRange=range;selected.clear();close();render();}catch(e){error(e);}};
}

function trendChart(){const data=snap.conflicts.length?[]:consumptionTrend(snap,selectedPeriod()),peak=Math.max(100,...data.map(r=>Math.abs(r.amount)));
 return `<div class="trend"><div class="chart-scale"><span>¥${moneyText(peak)}</span><span>¥0</span></div><div class="bars">${data.map((r,i)=>`<button class="bar-cell" title="${r.key} · ¥${moneyText(r.amount)}" data-trend="${r.key}" aria-label="${r.key} 净消费 ${moneyText(r.amount)} 元"><span class="bar ${r.amount<0?'negative':''}" style="height:${Math.max(2,Math.abs(r.amount)/peak*100)}%"></span>${i===0||i===data.length-1||i%Math.max(1,Math.round(data.length/4))===0?`<small>${r.key.length===7?r.key.slice(5):r.key.slice(5)}</small>`:''}</button>`).join('')}</div></div>`;
}
function categoryData(){const map=new Map<string,number>();if(!snap.conflicts.length)activeMonth().forEach(t=>{const e=effect(t.id);if(e)map.set(category(t.id),(map.get(category(t.id))||0)+Number(e.fields.amount));});return [...map].sort((a,b)=>b[1]-a[1]);}
function categoriesChart(){const data=categoryData().filter(([,v])=>v>0),sum=data.reduce((a,[,v])=>a+v,0),colors=['#b9dfb9','#819dcd','#dbc393','#aa96c8','#749e98','#c28f89','#8b949e'];if(!sum)return '<div class="chart-empty">有了消费记录，开销结构就会在这里出现。</div>';
 let start=0;const gradient=data.map(([,v],i)=>{const end=start+v/sum*100;const s=`${colors[i%colors.length]} ${start}% ${end}%`;start=end;return s;}).join(',');return `<div class="distribution"><div class="donut" role="img" aria-label="消费分类占比" style="background:conic-gradient(${gradient})"><div><small>最大开销</small><strong>${esc(data[0][0])}</strong><span>${Math.round(data[0][1]/sum*100)}%</span></div></div><div class="legend">${data.slice(0,5).map(([k,v],i)=>`<div><span><i style="background:${colors[i]}"></i>${esc(k)}</span><b>¥${moneyText(v)}</b></div>`).join('')}</div></div>`;
}
function billRows(list:Entity[],compact=false){if(!list.length)return empty('这里还没有账单','记下一笔，慢慢看见生活的轮廓。','new','记第一笔');return `<div class="bill-table ${compact?'compact':''}"><div class="table-head"><span>交易 / 时间</span><span>分类</span><span>账户</span><span>金额</span><span></span></div>${list.map(t=>{const f=t.fields,cat=category(t.id),e=effect(t.id),v=Number(f.display_amount),income=['INCOME','TRANSFER_IN','REFUND','RETURN'].includes(String(f.event_type));return `<div class="bill-row ${selected.has(t.id)?'selected':''}">${!compact?`<input class="row-select" type="checkbox" aria-label="选择 ${esc(f.display_name)}" data-select="${esc(t.id)}" ${selected.has(t.id)?'checked':''}>`:''}<button class="bill-main" data-detail="${esc(t.id)}"><span class="category-icon cat-${['餐饮','购物','交通','生活'].indexOf(cat)}">${categorySymbol(cat)}</span><span><strong>${esc(f.display_name)}</strong><small>${new Date(f.occurred_at as string).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}<span class="mobile-cat"> · ${esc(cat)}</span></small></span></button><span class="bill-category"><span class="tag">${esc(cat)}</span></span><span class="bill-account">${esc(accountLabel(t))}</span><button class="bill-amount ${income?'positive':''}" data-detail="${esc(t.id)}"><strong>${income?'+':f.event_type==='INTERNAL_TRANSFER'||f.event_type==='REPAYMENT'?'':'−'}${moneyText(v)}</strong><small>${f.status!=='SUCCESS'?statusNames[f.status as string]:e&&Number(e.fields.amount)!==0?typeNames[f.event_type as string]:'不计消费'}</small></button><button class="row-arrow icon-button" data-detail="${esc(t.id)}" aria-label="查看 ${esc(f.display_name)}">${icon('chevron')}</button></div>`;}).join('')}</div>`;}
function home(){const range=selectedPeriod(),consumed=total(),budget=budgetForPeriod(state.settings.budget,range)||0,remaining=consumed===null||!budget?null:budget-consumed,prev=total(previousPeriod(range,rangeMode)),change=consumed!==null&&prev!==null?consumptionChange(consumed,prev):null;const as=accounts();const known=as.map(a=>({a,b:balance(a)}));const assets=known.filter(x=>x.a.fields.type==='ASSET').reduce((s,x)=>s+(x.b||0),0),debt=known.filter(x=>x.a.fields.type==='LIABILITY').reduce((s,x)=>s+(x.b||0),0);const hasUnknown=known.some(x=>x.b===null);const recent=snap.conflicts.length?[]:majorBills(snap,range);
 return title('A LITTLE CLARITY, EVERY DAY','把生活，记得清楚。','关注真正的消费，也看清每一笔钱的去向。',`${monthPicker()}<button class="primary" data-action="new">${icon('plus')} 记一笔</button>`)+
 `<section class="overview-grid"><div class="spending-hero"><div class="hero-stars">✧</div><div class="card-label">${esc(rangeLabel())} 净消费 <span>退款已冲减</span></div><div class="hero-value"><small>¥</small>${moneyText(consumed)}</div><div class="hero-foot"><span>${change?.percent!==null&&change?.percent!==undefined?`${change.difference>=0?'↑':'↓'} 较上期 ${Math.abs(change.percent).toFixed(1)}%`:change?`较上期 ${change.difference>=0?'+':''}${moneyText(change.difference)} 元`:'从每一笔记录，认识自己的生活'}</span><span>${activeMonth().length} 笔记录</span></div></div><div class="stat-card"><div class="card-label">预算剩余<button class="text-button" data-action="budget">调整 ${icon('chevron')}</button></div><div class="stat-value ${remaining!==null&&remaining<0?'negative':''}">¥ ${moneyText(remaining)}</div><div class="progress"><i style="width:${consumed===null||!budget?0:Math.max(0,Math.min(100,consumed/budget*100))}%"></i></div><small>${budget?'本期预算 ¥'+moneyText(budget):'未设置预算'} ${remaining!==null&&remaining<0?'· 已超出预算':''}</small></div><div class="stat-card"><div class="card-label">已知净资产 ${icon('wallet')}</div><div class="stat-value">¥ ${snap.conflicts.length?'—':moneyText(assets-debt)}</div><div class="asset-mini"><span>资产 ¥${moneyText(assets)}</span><span>欠款 ¥${moneyText(debt)}</span></div><small>${hasUnknown?'部分账户余额暂不可计算，未计入合计':as.length?`${as.length} 个账户 · 余额由资金流水推导`:'添加账户，开始记录资金变化'}</small></div></section>
 <section class="quick-actions"><button data-action="capture"><span>${icon('camera')}</span><div><strong>截图记账</strong><small>选择支付详情截图</small></div>${icon('arrow')}</button><button data-page="import"><span>${icon('import')}</span><div><strong>导入账单</strong><small>微信 / 支付宝 · 补漏与核验</small></div>${icon('arrow')}</button><button data-action="account"><span>${icon('wallet')}</span><div><strong>管理账户</strong><small>钱包、银行卡与现金</small></div>${icon('arrow')}</button></section>
 ${!as.length&&!transactions().length?`<div class="welcome-note"><div><strong>从一份账单开始。</strong><p>导入微信或支付宝账单，系统帮你识别并准备账户；余额以后再补。</p></div><button class="secondary" data-action="import-file">导入账单</button><button class="text-button" data-action="demo">先看看演示</button></div>`:''}
 <section class="chart-grid"><div class="panel"><div class="panel-heading"><h2>消费轨迹</h2><span>按所选期间 · 元</span></div>${trendChart()}</div><div class="panel"><div class="panel-heading"><h2>钱花在哪里</h2><button class="text-button" data-page="analysis">查看分析 ${icon('arrow')}</button></div>${categoriesChart()}</div></section><section class="panel recent"><div class="panel-heading"><h2>本期大额账单 <small>${recent.length?'每一笔，都有迹可循':''}</small></h2><button class="text-button" data-page="bills">全部账单 ${icon('arrow')}</button></div>${billRows(recent,true)}</section>`;
}
function filteredBills(){return transactions().filter(t=>inMonth(t)&&(!query||`${t.fields.display_name} ${t.fields.note} ${category(t.id)}`.toLowerCase().includes(query.toLowerCase()))&&(!typeFilter||t.fields.event_type===typeFilter)&&(!statusFilter||t.fields.status===statusFilter)&&(!accountFilter||moves(t.id).some(m=>m.fields.account_id===accountFilter))).sort((a,b)=>String(b.fields.occurred_at).localeCompare(String(a.fields.occurred_at)));}
function bills(){const list=filteredBills();return title('YOUR EVERYDAY, IN DETAILS','账单','记录每一笔，也保留来源信息。',`${monthPicker()}<button class="secondary" data-page="import">${icon('import')} 导入</button><button class="primary" data-action="new">${icon('plus')} 记一笔</button>`)+`<div class="filter-bar"><label class="search">${icon('search')}<input id="search" placeholder="搜索商户、分类或备注" value="${esc(query)}"></label><select id="type-filter" aria-label="交易类型"><option value="">全部类型</option>${opts(Object.entries(typeNames),typeFilter)}</select><select id="account-filter" aria-label="筛选账户"><option value="">全部账户</option>${opts(accounts().map(a=>[a.id,a.fields.name]),accountFilter)}</select><select id="status-filter" aria-label="筛选状态"><option value="">全部状态</option>${opts(Object.entries(statusNames),statusFilter)}</select><button class="quiet" data-action="export-csv">导出 CSV</button></div><div class="list-summary"><span>${list.length} 笔账单 <span class="dim">· ${esc(rangeLabel())}</span></span><div><button class="text-button" data-action="select-all">${selected.size===list.length&&list.length?'取消全选':'全选'}</button><button class="text-button" data-action="trash">回收站</button></div></div>${selected.size?`<div class="selection-bar"><span>已选 ${selected.size} 笔</span><button data-action="batch-category">批量分类</button><button data-action="batch-delete">移到回收站</button><button data-action="deselect">取消选择</button></div>`:''}<section class="panel no-pad">${billRows(list)}</section>`;}
function importPage(){
 const unfinished=drafts.map((draft,index)=>({draft,index})).filter(({draft})=>!['committed','linked','ignored','noeffect'].includes(draft.workflow||''));
 return title('LESS TYPING, MORE LIVING','导入账单','选择微信或支付宝账单。',`<button class="secondary" data-action="capture">${icon('camera')} 截图记账</button><button class="primary" data-action="import-file">${icon('import')} 选择文件</button>`)+
 `${v2ImportSummary()}${unfinished.length?`<section class="panel"><h2>未完成记录 · ${unfinished.length}</h2>${unfinished.map(({draft,index})=>`<div class="trash-row"><div><strong>${esc(draft.name||'待补充记录')}</strong><small>${esc(draft.date.replace('T',' '))} · ¥ ${esc(draft.amount)}</small></div><button class="secondary" data-draft="${index}">继续填写</button></div>`).join('')}</section>`:''}${!Object.keys(state.importWorkspace?.sessions||{}).length&&!unfinished.length?'<section class="panel"><p>支持微信、支付宝 CSV / XLSX，以及支付详情截图。</p></section>':''}`;
}
function accountsPage(){return title('A PLACE FOR EVERY YUAN','账户','余额与消费各自计算，内部转账不会重复计入消费。','<button class="primary" data-action="account">'+icon('plus')+' 添加账户</button>')+`<div class="accounts-grid">${accounts().map((a,i)=>`<button class="account-card tone-${i%3}" data-account="${esc(a.id)}"><div class="account-card-top"><span class="account-symbol">${icon('wallet')}</span><span>${a.fields.type==='LIABILITY'?'负债账户':'资产账户'}</span>${icon('chevron')}</div><h2>${esc(a.fields.name)}</h2><p>${a.fields.type==='LIABILITY'?'当前欠款':'当前余额'}</p><strong>¥ ${moneyText(balance(a))}</strong><small>${a.fields.last4?'尾号 '+esc(a.fields.last4)+' · ':''}${esc(balanceStatus(a))}</small></button>`).join('')}<button class="account-card add-account" data-action="account">${icon('plus')}<strong>添加一个账户</strong><span>微信、支付宝、银行卡或现金</span></button></div>`;}
function analysis(){const range=selectedPeriod(),v=total(),data=categoryData(),budget=budgetForPeriod(state.settings.budget,range),stats=snap.conflicts.length?null:periodConsumption(snap,range),previous=previousPeriod(range,rangeMode),prev=total(previous),change=v!==null&&prev!==null?consumptionChange(v,prev):null;return title('UNDERSTAND YOUR RHYTHM','消费分析','看见开销结构，给下一次选择留一点空间。',`${monthPicker()}<button class="secondary" data-action="budget">设置月预算</button>`)+`<section class="analysis-stats"><div><small>本期消费</small><strong>¥ ${moneyText(stats?.spending??null)}</strong></div><div><small>本期退回</small><strong>¥ ${moneyText(stats?.refunds??null)}</strong></div><div><small>本期净消费</small><strong>¥ ${moneyText(v)}</strong><small>${budget?`本期预算 ¥ ${moneyText(budget)}`:'未设置月预算'}</small></div><div><small>较上期变化</small><strong>${change?`${change.difference>=0?'+':''}¥ ${moneyText(change.difference)}`:'—'}</strong><small>${change?.percent!==null&&change?.percent!==undefined?change.percent.toFixed(1)+'% · ':''}${previous.start} 至 ${previous.end}</small></div></section><section class="chart-grid"><div class="panel"><div class="panel-heading"><h2>消费轨迹</h2><span>退款计入发生日</span></div>${trendChart()}</div><div class="panel"><div class="panel-heading"><h2>消费构成</h2></div>${categoriesChart()}</div></section><section class="panel"><div class="panel-heading"><h2>分类明细</h2><span>按消费影响统计</span></div>${data.length?data.map(([k,n])=>`<div class="category-breakdown"><span class="category-icon">${categorySymbol(k)}</span><strong>${esc(k)}</strong><div class="progress"><i style="width:${Math.max(0,n/(Math.max(...data.map(x=>x[1]),1))*100)}%"></i></div><b>¥ ${moneyText(n)}</b></div>`).join(''):empty('还没有可分析的消费','完成记账后，分类明细会自动更新。')}<p class="footnote">收入、内部转账、还款不计消费。退款在退款发生期间冲减；负值分类表示本期退回超过新增消费。</p></section><section class="panel"><div class="panel-heading"><h2>本期大额账单</h2></div>${billRows(snap.conflicts.length?[]:majorBills(snap,range),true)}</section>`;}
function refreshDrafts(){drafts.forEach(d=>reviewDraft(d,snap.entities,snap.conflicts));const context=refundContext(snap.entities,drafts);drafts.forEach(d=>reviewDraft(d,snap.entities,snap.conflicts,context));}
function v2ImportSummary(){
 const workspace=state.importWorkspace;if(!workspace)return '';
 const sessions=Object.values(workspace.sessions||{}).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)||a.id.localeCompare(b.id));
 if(!sessions.length)return '';return sessions.map((session,index)=>index>0&&session.state==='COMPLETED'&&!(workspace.attention[session.id]?.length)?`<details class="panel"><summary>${esc(formatTime(session.updatedAt))} · 已处理 ${session.sourceCount} 条 · 查看导入结果</summary>${v2SessionSummary(session.id)}</details>`:v2SessionSummary(session.id)).join('');
}
function v2SessionSummary(sessionId:string){
 const workspace=state.importWorkspace!,session=workspace.sessions[sessionId];
 const questions=importQuestionGroups(workspace.attention[sessionId]??[],workspace.records[sessionId]??[]);
 const sourceLabel=session.sourceSystem==='WECHAT'?'微信':session.sourceSystem==='ALIPAY'?'支付宝':session.sourceSystem;
 const status=session.state==='FAILED'?'导入未完成':session.state==='PROCESSING'?'正在导入':questions.length?'已导入':'导入完成';
 return `<section class="panel" data-import-session="${esc(session.id)}"><div class="panel-heading"><div><h2>${esc(sourceLabel)} · ${status}</h2><p class="dim">${esc(formatTime(session.updatedAt))} · 共 ${session.sourceCount} 条来源</p></div></div>
 ${['PROCESSING','FAILED'].includes(session.state)?`<p><button class="secondary" data-v2-resume="${esc(session.id)}">继续导入</button></p>`:''}
 <section class="analysis-stats"><div><small>新增账单</small><strong>${session.committedCount}</strong></div><div><small>重复记录</small><strong>${session.skippedDuplicateCount}</strong></div><div><small>待处理</small><strong>${questions.length}</strong></div></section>
 ${questions.length?`<section class="batch-tools"><h3>待处理 · ${questions.length} 项</h3>${questions.map(({item,count})=>{
  const record=workspace.records[session.id]?.find(r=>r.id===item.externalRecordId);
  const actionable=item.blocking?['SOURCE_UPDATE','REFUND_RELATION','CONSUMPTION_ALLOCATION'].includes(item.kind):['ACCOUNT','TRANSFER_ENDPOINTS','REFUND_RELATION','CONSUMPTION_ALLOCATION'].includes(item.kind);
  return `<div class="trash-row"><div><strong>${esc(item.question)}${count>1?` · ${count} 笔`:''}</strong><small>${esc(record?.facts.channelRaw||'')} · ${esc(record?.facts.counterpartyRaw||'')}</small></div>${actionable?`<button class="secondary" data-v2-attention="${esc(item.id)}" data-session="${esc(session.id)}">确认</button>`:'<span class="tag">待确认</span>'}</div>`;
 }).join('')}</section>`:''}</section>`;
}

function conflictChoice(value:any){try{const v=JSON.parse(String(value));if(v?.accountId)return String(accountName(v.accountId));if(v?.transactionId)return '保留来源关联：'+String(getT(v.transactionId)?.fields.display_name||'已有交易');if(typeof v?.ignored==='boolean')return v.ignored?'忽略这条来源':'恢复来源待办';}catch{}return value===null?'停止记忆':String(value);}
function settingsPage(){const deleted=entities('transactions').filter(t=>t.fields.deleted_at&&!t.fields.purged_at).length;const aliasRules=snap.conflicts.length?[]:accountMemoryContext(snap).entries;return title('YOUR DATA, YOUR CHOICE','设置与同步','本地保存是默认，跨设备同步由你开启。')+`<div class="settings-grid"><section class="panel"><h2>云账户</h2>${localCloudIdentity()?`<p>当前账本：${esc(localCloudIdentity()!.username)}</p><p class="footnote" id="cloud-sync-status">${state.cloud?state.settings.lastSync?'上次同步：'+esc(formatTime(state.settings.lastSync)):'本地已保存，联网自动同步':'云同步尚未连接'}</p><div class="button-row"><button class="secondary" data-action="${state.cloud?'cloud-sync':'cloud-login'}">${state.cloud?'立即同步':'连接云同步'}</button><button class="quiet" data-action="cloud-key-backup" ${state.cloud?'':'disabled'}>保存恢复凭据</button><button class="quiet" data-action="cloud-logout">退出账户</button></div>`:`<p>使用用户名和密码登录你的个人账户。</p><button class="primary" data-action="cloud-login">登录</button>`}</section><section class="panel"><h2>关于与帮助</h2><button class="secondary" data-action="help">使用帮助</button></section><section class="panel"><h2>显示与偏好</h2><label>页面模式<select id="display-mode">${opts([['auto','自动适配设备'],['desktop','电脑模式'],['mobile','手机模式']],state.settings.mode)}</select></label><p class="footnote">电脑使用侧边导航和管理表格；手机使用底部导航、单列卡片和快捷输入。</p><label>月消费预算<div class="input-action"><input id="budget-input" type="number" min="0.01" step="0.01" value="${state.settings.budget===null?'':(state.settings.budget||0)/100}"><button class="secondary" data-action="save-budget">保存</button><button class="quiet" data-action="disable-budget">不设预算</button></div></label><label>分类管理<div class="category-chips">${state.settings.categories.map((c:string)=>`<span class="tag">${esc(c)}</span>`).join('')}</div><div class="input-action"><input id="category-name" placeholder="添加分类名称" maxlength="30"><button class="secondary" data-action="add-category">添加</button></div></label><p class="footnote">预算、分类目录及账单随加密同步共享；显示偏好仅保存在本机。备注中可使用 #标签 进行搜索。</p></section><section class="panel"><h2>备份与恢复</h2><p>导出完整账务记录，保存到你自己的设备。恢复采用合并方式，保留现有记录。</p><div class="button-row"><button class="secondary" data-action="backup">导出 JSON 备份</button><button class="secondary" data-action="restore">导入备份</button></div><p class="footnote">备份文件包含明文账单，请自行保管。浏览器清理网站数据会删除本机账本，建议定期备份。</p><button class="text-button" data-action="persist">申请持久存储</button><button class="text-button" data-action="trash">回收站 (${deleted})</button><button class="text-button" data-action="clear-import-queue">清除未完成记录</button><button class="text-button" data-action="reset-ledger">重置账本（清空所有数据）</button></section><section class="panel"><h2>已记住的账户关系</h2>${aliasRules.length?`<button class="quiet" data-action="forget-all-aliases">停止记忆全部 (${aliasRules.length})</button>`:''}${aliasRules.map(e=>`<div class="trash-row"><div>${e.scopes.map(v=>`<strong>${esc(v.platform)} · ${esc(v.profile)} · ${esc(v.channel)}</strong><small>${esc(v.role)} → ${esc(v.accountName)}${v.available?'':'（已停用）'}</small>`).join('')}${e.unreadable?'<small>旧记忆信息无法读取，当前不会据此确认账户。</small>':''}</div><button class="quiet" data-forget-alias="${esc(e.id)}">停止记忆</button></div>`).join('')||(snap.conflicts.length?'<p>先处理下方同步冲突，再查看或停止账户识别记忆。</p>':'<p>确认导入渠道后在这里查看。账户改名不影响关系。</p>')}<h2>关于这个版本</h2><p>星账 · 网页个人版 0.9 · 单人导入</p><p>电脑和手机访问同一个地址。账单保存在当前浏览器，完成同步配置后才能跨设备共享。</p><div class="button-row"><button class="secondary mobile-only" data-page="import">截图 / 账单导入</button><button class="secondary" data-action="help">使用说明</button>${!state.ops.length?'<button class="text-button" data-action="demo">体验演示账本</button>':''}</div><p class="footnote">全部金额以人民币分计算；未知余额显示为「—」。亲情卡、退款和内部转账使用独立的消费与余额规则。</p></section></div>${snap.conflicts.length?`<section class="panel"><h2>待解决的同步冲突</h2><p>保留双方修改，明确选择后才恢复统计。</p>${snap.conflicts.map((c,i)=>`<div class="conflict"><b>${c.entity_type==='ledger_settings'?(c.entity_id.endsWith(':budget')?'月预算设置':'分类目录设置'):esc(c.entity_type)+' · '+esc(c.field)}</b><small>${esc(c.entity_id)}</small>${(c.entity_type==='import_rules'||c.entity_type==='ledger_settings'||['note','category_id','display_name','name'].includes(c.field))?c.candidates.map((v,j)=>`<button class="secondary" data-resolve="${i}:${j}">采用：${esc(c.entity_type==='ledger_settings'?(c.entity_id.endsWith(':budget')?(v.value==='null'?'不设预算':'¥ '+moneyText(Number(v.value))):JSON.parse(String(v.value)).join('、')):c.entity_type==='import_rules'?conflictChoice(v.value):v.value)}</button>`).join(''):'<p>此项涉及整笔账务关联，本版暂不提供自动选择。请先导出备份并保留双方记录。</p>'}</div>`).join('')}</section>`:''}`;}
function render(){if(page==='bills'){const visible=new Set(filteredBills().map(t=>t.id));selected=new Set([...selected].filter(id=>visible.has(id)));}else selected.clear();const pages:Record<string,()=>string>={home,bills,accounts:accountsPage,analysis,import:importPage,settings:settingsPage};if(!pages[page])page='home';app.innerHTML=shell(pages[page]());}
function modal(title:string,content:string,wide=false){leaveDetailEditor();dialog.className=wide?'wide':'';dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="关闭">${icon('close')}</button></div><div class="modal-body">${content}</div>`;if(!dialog.open)dialog.showModal();}
function close(){leaveDetailEditor();dialog.close();dialog.innerHTML='';if(state)render();}
dialog.addEventListener('cancel',ev=>{ev.preventDefault();try{close();}catch(e){error(e);}});
function formData(form:HTMLFormElement){return Object.fromEntries(new FormData(form).entries()) as Record<string,string>;}
async function submit(form:HTMLFormElement,fn:()=>Promise<void>){const btn=form.querySelector<HTMLButtonElement>('button[type=submit]');if(btn?.disabled)return;if(btn)btn.disabled=true;try{await fn();}catch(e){error(e);}finally{if(btn)btn.disabled=false;}}
function newRecord(d?:Draft,index?:number,pending?:Entity){const x=d?structuredClone(d):{kind:'PURCHASE',name:'',amount:'',date:localDate(new Date()),status:'SUCCESS',account:accounts()[0]?.id||'',to:'',category:'餐饮',note:'',original:'',sponsor:false,consumption:'0'};const captureRevision=state.importRevision||0;let kind=x.kind;
 const body=()=>`<form id="record-form"><div class="form-grid"><label>交易类型<select name="kind" id="record-kind" ${pending?'disabled':''}>${opts(Object.entries(typeNames).filter(([k])=>k!=='UNKNOWN'||kind==='UNKNOWN'),kind)}</select></label><label>交易状态<select name="status" ${pending?'disabled':''}>${opts(Object.entries(statusNames).filter(([k])=>k!=='UNKNOWN'||x.status==='UNKNOWN'),pending?'SUCCESS':x.status)}</select></label><label class="span2 amount-input">金额 · 元<input name="amount" inputmode="decimal" value="${esc(x.amount)}" placeholder="0.00" required ${pending?'readonly':''}></label><label class="span2">${kind==='PURCHASE'?'商户 / 用途':'交易名称'}<input name="name" maxlength="100" value="${esc(x.name)}" placeholder="例如：午餐、生活用品" required></label><label class="span2">交易时间 · 北京时间<input name="date" type="datetime-local" step="1" value="${esc(x.date.length>10?x.date:'')}" required ${pending?'readonly':''}></label>${['REFUND','RETURN'].includes(kind)?`<label class="span2">关联原交易<select name="original"><option value="">先记录退款，稍后关联原交易</option>${opts(transactions().filter(t=>t.fields.status==='SUCCESS'&&(kind==='REFUND'?t.fields.event_type==='PURCHASE':['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(t.fields.event_type)))).map(t=>[t.id,`${t.fields.display_name} · ¥${moneyText(Number(t.fields.display_amount))} · ${String(t.fields.occurred_at).slice(0,10)}`]),x.original)}</select></label>`:''}<label class="${['INTERNAL_TRANSFER','REPAYMENT','WITHDRAWAL'].includes(kind)?'':'span2'}">${['INCOME','TRANSFER_IN','REFUND','RETURN'].includes(kind)?'到账账户':'付款 / 转出账户'}<select name="account">${accountOpts(x.account,true,kind,'account',x.to)}</select></label>${['INTERNAL_TRANSFER','REPAYMENT','WITHDRAWAL'].includes(kind)?`<label>转入账户<select name="to">${accountOpts(x.to,true,kind,'to',x.account)}</select></label>`:''}${['PURCHASE','REFUND','RETURN'].includes(kind)?`<label class="check-label span2"><input name="sponsor" type="checkbox" ${x.sponsor?'checked':''}> 亲情卡 / 他人代付（不扣本人余额）</label>`:''}${['PURCHASE','EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(kind)?`<label>消费分类<select name="category">${opts([...new Set([...state.settings.categories,x.category])].map((c:any)=>[String(c),c]),x.category)}</select></label>`:''}${['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET','RETURN'].includes(kind)?`<label>${kind==='RETURN'?'冲减消费金额':'其中计入消费 · 元'}<input name="consumption" inputmode="decimal" value="${esc(x.consumption||'0')}"></label>`:''}${kind==='WITHDRAWAL'?`<label>手续费 · 元<input name="fee" value="${esc((x as any).fee||'0')}" inputmode="decimal"></label>`:''}<label class="span2">备注 / #标签<textarea name="note" rows="2" maxlength="1000" placeholder="留一点关于这笔钱的记忆">${esc(x.note)}</textarea></label></div>${d?.key&&matchCandidates(d).length?`<div class="match-box"><strong>发现可能是同一笔的记录</strong><p>核对后可只补充来源，不再新增消费。</p><select id="match-existing">${opts(matchCandidates(d).map(t=>[t.id,`${t.fields.display_name} · ¥${moneyText(Number(t.fields.display_amount))} · ${new Date(String(t.fields.occurred_at)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}`]),'')}</select><button type="button" class="secondary" id="attach-source">关联这笔，补充凭证</button><label class="check-label"><input name="independent" type="checkbox">我已核对，这是另一笔独立交易</label></div>`:''}${d?`<details class="source-details"><summary>查看原始凭证</summary><pre>${esc(d.raw)}</pre></details>`:'<p class="footnote">待完成 / 未成功的交易暂不影响余额和消费。付款账户留空时保留待补认资金变动。</p>'}<div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">${pending?'确认交易成功':'保存账单'}</button></div></form>`;
 const draw=()=>{modal(pending?'完成待支付交易':d?'补充记录':'记一笔',body());if(d&&$('#attach-source'))$('#attach-source').onclick=async()=>{try{await attachSource(d,$<HTMLSelectElement>('#match-existing').value);}catch(e){error(e);}};$('#record-form [name=account]')?.addEventListener('change',()=>{const form=$<HTMLFormElement>('#record-form'),v=formData(form);Object.assign(x,v,{sponsor:v.sponsor==='on'});if(x.to===x.account)x.to='';draw();});$('#record-kind')?.addEventListener('change',e=>{const values=formData($('#record-form'));Object.assign(x,values,{sponsor:values.sponsor==='on'});kind=(e.target as HTMLSelectElement).value;x.kind=kind;x.account='';x.to='';draw();});$('#record-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target as HTMLFormElement;submit(form,async()=>{const v=formData(form);v.kind=pending?String(pending.fields.event_type):kind;v.status=pending?'SUCCESS':v.status;const draft={...d,...v,sponsor:v.sponsor==='on'} as any;const cmd=commandFrom(draft);if(index!==undefined){if(draft.kind==='UNKNOWN'||draft.status==='UNKNOWN')throw Error('请确认交易性质和状态');await saveCapturedRecord({index,expectedRevision:captureRevision,event:cmd,independent:v.independent==='on'});await refresh();close();toast('已保存到账本');return;}if(d&&duplicate(d)&&!pending)throw Error('这条记录已经存在，请到导入页查看，避免重复记账');if(pending){cmd.id=pending.id;cmd.occurredAt=String(pending.fields.occurred_at);await business({kind:'SET_STATUS',transactionId:pending.id,status:'SUCCESS',settlement:cmd});}else await business(cmd);await refresh();close();toast('已保存到账本');});});};draw();}
function commandFrom(v:any):FinancialEvent{const amount=money(String(v.amount));const date=new Date(sourceUTC(v.date));if(!Number.isFinite(date.getTime()))throw Error('请填写有效的交易时间');const base={id:v.key?importTransactionId(v):crypto.randomUUID(),occurredAt:date.toISOString(),name:v.name.trim(),amount,status:v.status as any,note:v.note||'',...(v.key?{source:{id:crypto.randomUUID(),sourceType:v.sourceType,platform:v.platform,rawPayload:JSON.stringify(sourcePayload(v))}}:{})};const a=v.account||null;const zero=(s:any)=>s===''||s===undefined||Number(s)===0?0:money(String(s));switch(v.kind){case 'PURCHASE':return {...base,kind:v.kind,payer:v.sponsor?null:a,categoryId:v.category,funding:v.sponsor?'EXTERNAL_SPONSOR':'OWN'};case 'INCOME':case 'TRANSFER_IN':return {...base,kind:v.kind,destination:a};case 'INTERNAL_TRANSFER':return {...base,kind:v.kind,from:a,to:v.to||null};case 'WITHDRAWAL':return {...base,kind:v.kind,from:a,to:v.to||null,fee:zero(v.fee)};case 'REPAYMENT':return {...base,kind:v.kind,from:a!,to:v.to};case 'REFUND':return {...base,kind:v.kind,originalId:v.original||null,destination:v.sponsor?null:a,funding:v.sponsor?'EXTERNAL_SPONSOR':'OWN',categoryId:v.category};case 'RETURN':return {...base,kind:v.kind,originalId:v.original||null,destination:v.sponsor?null:a,funding:v.sponsor?'EXTERNAL_SPONSOR':'OWN',categoryId:v.category,consumptionReduction:v.originalMode==='manual'?zero(v.consumption):undefined};case 'EXTERNAL_TRANSFER':case 'DEPOSIT':case 'RED_PACKET':return {...base,kind:v.kind,from:a,consumptionAmount:zero(v.consumption),categoryId:v.category};default:throw Error('未知交易类型');}}
function accountDialog(id?:string){const a=id?accounts().find(a=>a.id===id):undefined;modal(a?'账户详情':'添加账户',`<form id="account-form"><div class="form-grid"><label class="span2">账户名称<input name="name" placeholder="例如：招商银行卡、微信余额" value="${esc(a?.fields.name||'')}" maxlength="60" required></label><label>账户类型<select name="type" ${a?'disabled':''}>${opts([['ASSET','资产 · 钱包 / 银行卡 / 现金'],['LIABILITY','负债 · 信用账户']],a?.fields.type||'ASSET')}</select></label><label>尾号（可选）<input name="last4" pattern="[0-9]{0,4}" maxlength="4" value="${esc(a?.fields.last4||'')}"></label><label>期初余额 / 欠款 · 元<input name="balance" inputmode="decimal" placeholder="不确定可以留空" value="${a?.fields.balance_state==='ESTABLISHED'?Number(a.fields.opening_balance)/100:''}"></label><label>期初时刻 · 北京时间<input name="date" type="datetime-local" step="1" value="${a?localDate(new Date(a.fields.opening_balance_at as string)):localDate(new Date(Date.now()-1000))}" required></label></div><p class="footnote">填写这个时刻的余额，系统只累加此后发生的流水。导入历史账单时，请特别注意期初时刻。留空表示余额未知。</p>${a?`<div class="balance-line">当前${a.fields.type==='LIABILITY'?'欠款':'余额'}<strong>¥ ${moneyText(balance(a))}</strong></div>`:''}${a?`<div><h3>来源别名</h3>${accountMemoryContext(snap).entries.flatMap(e=>e.scopes.filter(v=>v.accountId===a.id)).map(v=>`<p>${esc(v.platform)} · ${esc(v.channel)}</p>`).join('')||'<p class="dim">确认导入账户后会记录在这里。</p>'}<button type="button" class="secondary" id="manage-account-alias">管理来源别名</button></div>`:''}<div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">保存账户</button></div></form>`);const manage=$<HTMLButtonElement>('#manage-account-alias');if(manage)manage.onclick=()=>{const v=formData($<HTMLFormElement>('#account-form'));if(v.name!==String(a!.fields.name)||v.last4!==String(a!.fields.last4||'')){toast('请先保存账户修改，再管理别名');return;}accountAliasDialog(a!.id);};$('#account-form').addEventListener('submit',e=>{e.preventDefault();const form=e.target as HTMLFormElement;submit(form,async()=>{const v=formData(form);const n=v.balance.trim()===''?null:Number(v.balance)===0?0:money(v.balance),at=sourceUTC(v.date);if(a){const fields={name:v.name,last4:v.last4,opening_balance:n??0,opening_balance_at:at,balance_state:n===null?'UNINITIALIZED':'ESTABLISHED'};await raw(Object.entries(fields).map(([k,value])=>({action:'PATCH_FIELD',entity:{type:'accounts',id:a.id,fields:{[k]:value}}})));}else await business({kind:'CREATE_ACCOUNT',id:crypto.randomUUID(),name:v.name,accountType:v.type as any,openingBalance:n,openingBalanceAt:at,last4:v.last4});await refresh();close();toast('账户已保存');});});}
function accountAliasDialog(id:string){
 const account=accounts().find(a=>a.id===id);if(!account)throw Error('ACCOUNT_UNAVAILABLE');const context=accountMemoryContext(snap),entries=context.entries.filter(e=>e.scopes.some(v=>v.accountId===id));
 modal('来源别名 · '+String(account.fields.name),`<p>显示名称：${esc(account.fields.name)}</p>${entries.map(e=>`<div class="trash-row"><div>${e.scopes.map(v=>`<strong>${esc(v.platform)} · ${esc(v.channel)}</strong><small>${esc(v.profile)} · ${esc(v.role)}</small>`).join('')}</div><button class="quiet" data-forget-alias="${esc(e.id)}">停止记忆</button></div>`).join('')}<form id="account-alias-form"><label>账单来源<select name="platform">${opts([['微信','微信'],['支付宝','支付宝']],'微信')}</select></label><label>来源里的账户名称<input name="channel" maxlength="100" placeholder="例如：农业银行储蓄卡(2372)" required></label><label>账单归属<input name="profile" value="本人" maxlength="60" required></label><p class="footnote">别名用于识别到账单里的账户名称；不会改动已保存账单的资金账户。</p><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">保存别名</button></div></form>`);
 const form=$<HTMLFormElement>('#account-alias-form');form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{const v=formData(form);await setAccountAlias({accountId:id,platform:v.platform as '微信'|'支付宝',profile:v.profile,channel:v.channel,expectedSnapshot:context.expectedSnapshot,now:new Date().toISOString()});await refresh();close();toast('来源别名已保存');});};
}
function evidenceView(source:Entity){
 const f=source.fields;
 if(f.source_type==='MANUAL'&&f.platform==='星账 · 金额更正'){
  try{const v=JSON.parse(String(f.raw_payload));if(v.kind==='AMOUNT_CORRECTION'&&Number.isSafeInteger(v.before)&&Number.isSafeInteger(v.after))return `<div class="correction-evidence"><p><strong>金额更正：¥ ${moneyText(v.before)} → ¥ ${moneyText(v.after)}</strong></p><p>原因：${esc(v.reason)}</p><p class="footnote">${esc(new Date(v.correctedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}))} · 保留原交易与原始凭证</p></div>`;}catch{}
 }
 return `<p>${esc(f.platform)} · ${esc(f.source_type)}</p><pre>${esc(f.raw_payload)}</pre>`;
}
function detail(id:string,draftId?:string){const t=getT(id);if(!t||t.fields.deleted_at||t.fields.purged_at){if(draftId)modal('未保存的修改',unavailableDetailDraft(state.device,draftId));return;}const f=t.fields,effectRow=effect(id),sources=entities('source_records').filter(s=>s.fields.transaction_id===id);const list=filteredBills(),at=list.findIndex(x=>x.id===id);modal('账单详情',`<div class="detail-hero"><span class="category-icon">${categorySymbol(category(id))}</span><h3>${esc(f.display_name)}</h3><strong>¥ ${moneyText(Number(f.display_amount))}</strong><span class="tag">${typeNames[String(f.event_type)]} · ${statusNames[String(f.status)]}</span></div><div class="detail-facts"><span>发生时间</span><b>${new Date(String(f.occurred_at)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</b><span>资金账户</span><b>${esc(accountLabel(t))}</b><span>对消费的影响</span><b>¥ ${moneyText(Number(effectRow?.fields.amount||0))}</b></div>${relatedTransactions(snap,id).length?`<section id="detail-relations"><p>相关账单</p>${relatedTransactions(snap,id).map(row=>`<button type="button" class="secondary" data-detail="${esc(row.transaction!.id)}">${row.direction==='original'?'原消费 / 转出':'退款 / 退回'}：${esc(row.transaction!.fields.display_name)} · ¥ ${moneyText(Number(row.transaction!.fields.display_amount))} · ${formatTime(row.transaction!.fields.occurred_at)}</button>`).join('')}</section>`:''}<form id="detail-form"><label>名称<input name="name" value="${esc(f.display_name)}" maxlength="100" required></label>${`<label>分类<select name="category">${opts([...new Set([...state.settings.categories,category(id)])].map(c=>[String(c),c]),category(id))}</select></label>`}<label>备注 / #标签<textarea name="note" rows="3" maxlength="1000">${esc(f.note)}</textarea></label><div class="button-row">${moves(id).filter(m=>m.fields.account_id===null).map(m=>`<button type="button" class="secondary" data-bind="${esc(m.id)}">补认${Number(m.fields.amount)<0?'付款':'收款'}账户</button>`).join('')}${f.status==='SUCCESS'&&['EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(f.event_type))?`<button type="button" class="secondary" data-meaning="${esc(id)}">调整消费用途</button>`:''}${f.status==='SUCCESS'&&['REFUND','RETURN'].includes(String(f.event_type))?`<button type="button" class="secondary" data-link-return="${esc(id)}">修改退款关联</button>`:''}${f.status==='SUCCESS'&&['PURCHASE','EXTERNAL_TRANSFER','DEPOSIT','RED_PACKET'].includes(String(f.event_type))?`<button type="button" class="secondary" data-refund="${esc(id)}">记录退款 / 退回</button>`:''}${f.status==='PENDING'?`<button type="button" class="secondary" data-settle="${esc(id)}">确认成功</button><button type="button" class="secondary" data-fail="${esc(id)}">标记失败</button>`:''}</div>${sources.length?`<details class="source-details"><summary>查看来源原始字段 (${sources.length})</summary>${sources.map(evidenceView).join('')}</details>`:'<p class="footnote">手动记录。可直接修改账单信息，系统保留修改历史。</p>'}<div class="modal-actions"><button type="button" class="danger quiet" data-delete="${esc(id)}">移至回收站</button><div>${at>0?`<button type="button" class="quiet" data-detail="${esc(list[at-1].id)}">上一笔</button>`:''}${at>=0&&at<list.length-1?`<button type="button" class="quiet" data-detail="${esc(list[at+1].id)}">下一笔</button>`:''}<button type="submit" class="primary">保存修改</button></div></div></form>`);installDetailEditor({form:$<HTMLFormElement>('#detail-form'),device:state.device,id,snapshot:snap,draftId,error,done:async()=>{await refresh();close();toast('账单编辑已完成');}});}
function confirmAction(title:string,message:string,fn:()=>Promise<void>,label='确认'){modal(title,`<p>${message}</p><form id="confirm-form"><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button class="primary" type="submit">${label}</button></div></form>`);$('#confirm-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await fn();await refresh();close();});});}
function forgetMemoryDialog(entryIds:readonly string[]|'ALL'){
 const context=accountMemoryContext(snap),chosen=entryIds==='ALL'?context.entries:context.entries.filter(e=>entryIds.includes(e.id));
 const names=chosen.flatMap(e=>e.scopes.map(v=>`${v.platform} · ${v.profile} · ${v.channel} → ${v.accountName}`));
 confirmAction('停止记忆账户关系',`将停止以下 ${chosen.length} 组识别记忆：${names.join('；')||'旧版账户识别'}。仅影响以后的自动识别，已保存账单不变。`,async()=>{await forgetAccountMemory({entryIds,expectedSnapshot:context.expectedSnapshot});},'确认停止');
}
function refund(id:string){const t=getT(id);const originalMoves=moves(id);const refundKind=t.fields.event_type==='PURCHASE'?'REFUND':'RETURN';newRecord({key:'',platform:'手动',name:'退回 · '+t.fields.display_name,amount:'',date:localDate(new Date()),kind:refundKind,status:'SUCCESS',channel:'',account:String(originalMoves[0]?.fields.account_id||''),to:'',category:category(id),original:id,note:'',raw:'',issue:'',selected:false,sourceType:'EXCEL',order:'',sponsor:false,consumption:'0'});}
function duplicate(d:Draft){return existingSource(d,snap.entities)[0];}
function matchCandidates(d:Draft){return safeCandidates(d,snap.entities);}
async function attachSource(d:Draft,id:string){if(duplicate(d))throw Error('这条来源已经存在，请查看原记录');if(!matchCandidates(d).some(t=>t.id===id))throw Error('请选择候选交易');await mutate(store=>{if(existingSource(d,store.entities).length)throw Error('来源已被另一窗口处理');new AccountingService(store,store.state.device).execute([{action:'CREATE_ENTITY',entity:{type:'source_records',id:'source-'+hash({key:d.key,raw:d.raw}),fields:{transaction_id:id,source_type:d.sourceType,platform:d.platform,raw_payload:JSON.stringify(sourcePayload(d)),created_at:sourceUTC(d.date)}}},ruleCommand(store.entities,'source-'+(d.identity||d.key),{transactionId:id})]);const draft=store.state.imports?.find(x=>x.itemId===d.itemId);if(draft){draft.workflow='linked';draft.transactionId=id;draft.selected=false;store.state.importRevision=(store.state.importRevision||0)+1;}});await refresh();close();toast('已关联来源，没有新增消费');}

async function importAttentionDialog(sessionId:string,attentionId:string){
 const refundItem=state.importWorkspace?.attention[sessionId]?.find(e=>e.id===attentionId&&['REFUND_RELATION','CONSUMPTION_ALLOCATION'].includes(e.kind));if(refundItem){let outcome=state.importWorkspace?.outcomes[sessionId]?.find(e=>e.externalRecordId===refundItem.externalRecordId);if(refundItem.kind==='CONSUMPTION_ALLOCATION'&&outcome?.state==='BLOCKED'){await resumeImportSession(sessionId);await refresh();outcome=state.importWorkspace?.outcomes[sessionId]?.find(e=>e.externalRecordId===refundItem.externalRecordId);}if(!outcome?.transactionId)throw Error('IMPORT_RECORD_NOT_COMMITTED');linkReturnDialog(outcome.transactionId);return;}

 const workspace=state.importWorkspace,item=workspace?.attention[sessionId]?.find(value=>value.id===attentionId);
 const source=workspace?.records[sessionId]?.find(value=>value.id===item?.externalRecordId);
 if(!item||!source)throw Error('STALE_IMPORT_ATTENTION');
 if(item.kind==='TRANSFER_ENDPOINTS'&&!item.blocking){
  const context=transferAttentionContext(sessionId,attentionId,workspace!,snap);
  const repayment=context.transaction.fields.event_type==='REPAYMENT';
  const fromName=accounts().find(a=>a.id===context.from.fields.account_id)?.fields.name||'付款账户待补充';
  const bound=typeof context.to.fields.account_id==='string';
  modal(repayment?'这笔还款还到了哪里？':'这笔钱转入哪个账户？',`<form id="v2-transfer-form"><p>${esc(context.transaction.fields.display_name)} · ¥ ${moneyText(Number(context.transaction.fields.display_amount))}</p><p>付款账户：${esc(fromName)}</p><label>${repayment?'信用卡 / 负债账户':'收款账户'}<select name="account" required><option value="">请选择</option>${opts(context.accounts.map(a=>[a.id,String(a.fields.name)]),bound?String(context.to.fields.account_id):'')}${bound?'':'<option value="__new">新建账户</option>'}</select></label><div id="v2-transfer-new" hidden><label>账户名称<input name="name" maxlength="80" placeholder="${repayment?'例如：我的花呗':'例如：日常储蓄卡'}"></label></div><p class="footnote">${context.transaction.fields.status==='PENDING'?'这笔记录仍在处理中，只补齐未来入账账户。':'同目标账户的记录会一起补齐，不新增交易或重复计算消费。'}${!context.from.fields.account_id?'付款账户可通过原来的渠道问题统一补齐。':''}</p><div class="modal-actions"><button type="submit" class="primary">保存账户</button></div></form>`);
  const form=$<HTMLFormElement>('#v2-transfer-form');form.querySelector<HTMLSelectElement>('[name=account]')!.onchange=()=>{$('#v2-transfer-new').hidden=formData(form).account!=='__new';};
  form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{
   const value=formData(form),create=value.account==='__new',id=create?crypto.randomUUID():value.account,now=new Date().toISOString();
   if(!id)throw Error('ACCOUNT_UNAVAILABLE');if(create&&!value.name.trim())throw Error('请填写账户名称');
   await answerImportTransfer({sessionId,attentionId,accountId:id,expectedSnapshot:context.expectedSnapshot,now,createAccount:create?{kind:'CREATE_ACCOUNT',id,name:value.name.trim(),accountType:context.accountType,openingBalance:null,openingBalanceAt:now,last4:describeFundingChannel(source.platformRaw,source.facts.targetChannelRaw||'')?.last4}:undefined});
   await refresh();close();toast('目标账户已补齐，没有新增交易');
  });};return;
 }
 if(item.kind==='SOURCE_UPDATE'){
  const review=await previewImportSource(sessionId,attentionId),target=review.context.target;
  const fields=(tx:any)=>tx?`${moneyText(Number(tx.fields.display_amount))} 元 · ${esc(typeNames[String(tx.fields.event_type)]||String(tx.fields.event_type))} · ${esc(statusNames[String(tx.fields.status)]||String(tx.fields.status))}<br>${esc(formatTime(tx.fields.occurred_at))}`:'尚未入账';
  const describeMovements=(movements:any[])=>movements.map(m=>`${esc(String(review.accounts.find(a=>a.id===m.fields.account_id)?.fields.name||'账户待补充'))}：${moneyText(Number(m.fields.amount))}`).join('；')||'无实际账户变动';
  const labels={KEEP_EXISTING:target?.fields.deleted_at?'恢复并保留原账单':'保留现有账单',APPLY_SOURCE:target?.fields.deleted_at?'恢复并采用新来源':'采用这份来源'};
  modal('核对来源变化',`<form id="v2-source-form"><p>当前账单：${fields(target)}</p><p>来源记录：${esc(source.facts.counterpartyRaw)} · ${moneyText(source.facts.amountFen)} 元 · ${esc(source.facts.statusRaw)} · ${esc(source.facts.channelRaw)}</p><p class="footnote">采用来源将更新账务信息，保留已有名称、备注和消费分类。原始证据仍会保留。${!target?'同一订单的其他矛盾版本将保留为未采用的证据。':''}</p>${review.options.map(option=>`<label class="source-choice"><input type="radio" name="mode" value="${option.mode}" required ${option.plan?'':'disabled'}> ${labels[option.mode]}</label><p class="footnote">${option.plan?`${fields(option.plan.preview)}<br>${describeMovements(option.plan.movements)}`:esc(sourceAnswerMessages[option.error||'']||'这项处理暂不可用，请先核对其他问题')}</p>`).join('')}<details><summary>查看原始来源</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(source.rawPayload)}</pre></details><div class="modal-actions"><button type="submit" class="primary" ${review.options.some(o=>o.plan)?'':'disabled'}>确认处理</button></div></form>`);
  const form=$<HTMLFormElement>('#v2-source-form');form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{
   const mode=formData(form).mode;if(mode!=='KEEP_EXISTING'&&mode!=='APPLY_SOURCE')throw Error('INVALID_SOURCE_DECISION');
   await answerImportSource(sessionId,attentionId,mode,review.context.token);await refresh();close();toast('来源处理决定已保存');
  });};return;
 }
 if(item.kind!=='ACCOUNT'||item.blocking)throw Error('STALE_IMPORT_ATTENTION');
 const descriptor=describeFundingChannel(source.platformRaw,source.facts.channelRaw);
 const list=accounts().filter(a=>!descriptor||a.fields.type===descriptor.type);
 modal('确认资金账户',`<form id="v2-account-form"><p>${esc(source.facts.channelRaw)} 对应哪个账户？</p><label>账户<select name="account"><option value="__new">新建账户</option>${opts(list.map(a=>[a.id,String(a.fields.name)]),'')}</select></label><div id="v2-new-account"><label>新账户名称<input name="name" value="${esc(descriptor?.name||source.facts.channelRaw)}" maxlength="80"></label><label>账户类型<select name="accountType">${opts([['ASSET','余额 / 储蓄账户'],['LIABILITY','信用 / 负债账户']],descriptor?.type||'ASSET')}</select></label></div><p class="footnote">同渠道记录一起补齐，余额可稍后设置。</p><label class="check-label"><input name="remember" type="checkbox" checked>以后同渠道使用此账户</label><div class="modal-actions"><button type="submit" class="primary">确认账户</button></div></form>`);
 const form=$<HTMLFormElement>('#v2-account-form');
 form.querySelector<HTMLSelectElement>('[name=account]')!.onchange=()=>{$('#v2-new-account').hidden=formData(form).account!=='__new';};
 form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{
  const value=formData(form),now=new Date().toISOString(),create=value.account==='__new',id=create?crypto.randomUUID():value.account;
  if(create&&!value.name.trim())throw Error('请填写账户名称');
  const count=await answerImportAccount({sessionId,attentionId,accountId:id,now,remember:!!value.remember,createAccount:create?{kind:'CREATE_ACCOUNT',id,name:value.name.trim(),accountType:value.accountType as 'ASSET'|'LIABILITY',openingBalance:null,openingBalanceAt:now,last4:descriptor?.last4}:undefined});
  await refresh();close();toast(`已补齐 ${count} 笔记录的账户${value.remember?'，并记住渠道关系':'，仅用于本批'}`);
 });};
}

async function importFile(){
 const file=await chooseFile('.xlsx,.csv');if(!file)return;if(file.size>15*1024*1024)throw Error('账单文件不能超过15 MB');
 let rows:any[][];
 if(file.name.toLowerCase().endsWith('.csv')){const bytes=await file.arrayBuffer();let text=new TextDecoder('utf-8').decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('gb18030').decode(bytes);rows=csv(text);}else{const {default:readXlsxFile}=await import('read-excel-file');rows=await readXlsxFile(file);}
 const incoming=parseRows(rows,{profile:'本人',batch:hash(rows)});if(!incoming.length)throw Error('没有识别到可导入的账单记录');
 const now=new Date().toISOString(),sessionId='import-'+crypto.randomUUID();
 // Legacy aliases are migrated only when their meaning is safe; target aliases remain deliberately unmigrated.
 await migrateLegacyResolutionMemory(now);await refresh();
 const workspace=new WebImportWorkspaceRepository(),service=new ImportStatementService(workspace,new LedgerResolutionMemoryRepository());
 const resolved=await resolveLegacyImportBatch({drafts:incoming,sessionId,ledger:snap,now,service});
 const committed=await commitResolvedWebImport(resolved,now);
 await refresh();setPage('import');
 const s=committed.session;
 const pending=importQuestionGroups(state.importWorkspace?.attention[sessionId]??[],state.importWorkspace?.records[sessionId]??[]).length;toast('导入完成 · 新增 '+s.committedCount+' 笔 · 重复 '+s.skippedDuplicateCount+' 笔'+(pending?' · 待处理 '+pending+' 项':''));
}
function chooseFile(accept:string):Promise<File|undefined>{return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>resolve(input.files?.[0]);input.addEventListener('cancel',()=>resolve(undefined));input.click();});}
function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function capture(){const file=await chooseFile('image/png,image/jpeg,image/webp');if(!file)return;if(file.size>12*1024*1024)throw Error('截图不能超过 12 MB');const fingerprint=hash(Array.from(new Uint8Array(await file.arrayBuffer())));const preview=URL.createObjectURL(file);const controller=new AbortController();let cancelled=false;modal('截图识别',`<div class="capture-preview"><img src="${preview}" alt="待识别支付截图"><div><h3>图片留在你的设备</h3><p id="ocr-progress">准备文字识别资源…</p><p class="footnote">首次使用需要联网准备识别资源；准备后可离线识别。金额、日期与付款账户可在结果中修改。</p><button class="secondary" id="cancel-ocr">停止识别</button></div></div>`);const stop=()=>{cancelled=true;controller.abort();URL.revokeObjectURL(preview);};dialog.addEventListener('close',stop,{once:true});$('#cancel-ocr').onclick=()=>close();try{const text=await recognizeImage(file,controller.signal,m=>{if(!cancelled&&$('#ocr-progress'))$('#ocr-progress').textContent=m.status==='recognizing text'?`正在识别文字… ${Math.round(m.progress*100)}%`:'正在准备识别资源…';});if(cancelled)return;dialog.removeEventListener('close',stop);URL.revokeObjectURL(preview);const d=parseScreenshot(text,fingerprint);await mutate(store=>{if(!(store.state.imports||[]).some(x=>x.itemId===d.itemId)){store.state.imports=[...(store.state.imports||[]),d];store.state.importRevision=(store.state.importRevision||0)+1;}});await refresh();setPage('import');const index=drafts.findIndex(x=>x.itemId===d.itemId);if(index>=0&&['committed','linked','ignored','noeffect'].includes(drafts[index].workflow||'')){close();toast('这张截图已处理');return;}newRecord(d,index);}catch(e){if(!cancelled){dialog.removeEventListener('close',stop);controller.abort();URL.revokeObjectURL(preview);modal('暂时无法识别',`<p>文字识别资源加载或识别失败。你可以稍后重试，也可以手动记下这笔交易。</p><p class="footnote">图片未上传到账本外的服务器。</p><button class="primary" data-action="new">手动记一笔</button>`);}}}
function trash(){const ts=entities('transactions').filter(t=>t.fields.deleted_at&&!t.fields.purged_at);modal('回收站',ts.length?`<p class="footnote">移除的交易不参与统计，原始证据仍保留。重新导入相同来源会识别为已有记录，可在这里恢复。彻底删除后将从回收站消失，重导按新交易入账。</p><div class="button-row"><button class="secondary" data-restore-all="1">恢复全部 ${ts.length} 笔</button><button class="quiet" data-purge-all="1">清空回收站（彻底删除全部 ${ts.length} 笔）</button></div>${ts.map(t=>`<div class="trash-row"><div><strong>${esc(t.fields.display_name)}</strong><small>¥ ${moneyText(Number(t.fields.display_amount))}</small></div><div class="button-row"><button class="secondary" data-restore="${esc(t.id)}">恢复</button><button class="quiet" data-purge="${esc(t.id)}">彻底删除</button></div></div>`).join('')}`:'<p>回收站是空的。</p>');}
function lifecycleDialog(action:LifecycleAction,ids:string[]){
 const context=lifecycleContext(snap,action,ids),restoring=action==='RESTORE';
 const rows=context.targets.map(t=>`<li>${esc(t.fields.display_name)} · ¥ ${moneyText(Number(t.fields.display_amount))}</li>`).join('');
 const message=`<p>${restoring?'恢复':'移至回收站'}以下 ${context.transactionIds.length} 笔账单，保留金额、账户和此前修改。</p><ul>${rows}</ul><p>${restoring?'系统会重验因删除而解除的退款关系，仍有效的自动恢复；不满足条件的保留到账事实并提示继续处理。':`原始凭证保留。${context.affectedRefundIds.length?`系统将解除 ${context.affectedRefundIds.length} 笔退款的关联；未选中的退款不会删除，到账事实仍保留。`:''}`}</p>`;
 confirmAction(restoring?'恢复账单':'移至回收站',message,async()=>{await saveTransactionLifecycle({action,transactionIds:context.transactionIds,expectedSnapshot:context.expectedSnapshot,now:new Date().toISOString()});selected.clear();},restoring?'确认恢复':'确认移除');
}
function purgeTransaction(id:string){modal('彻底删除',`<p>彻底删除后此记录将从回收站消失，重新导入相同来源会作为新交易入账。此操作不可撤销。</p><form id="purge-form"><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button class="danger" type="submit">确认彻底删除</button></div></form>`);$('#purge-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await mutate(store=>{new AccountingService(store,store.state.device).execute([{action:'PATCH_FIELD',entity:{type:'transactions',id,fields:{purged_at:new Date().toISOString()}}}]);});await refresh();trash();});});}
function purgeAllTransactions(){const ids=entities('transactions').filter(t=>t.fields.deleted_at&&!t.fields.purged_at).map(t=>t.id);if(!ids.length)return;modal('清空回收站',`<p>将彻底删除回收站中的 ${ids.length} 笔记录。此操作不可撤销，重新导入相同来源会作为新交易入账。</p><form id="purge-all-form"><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button class="danger" type="submit">确认清空</button></div></form>`);$('#purge-all-form').addEventListener('submit',e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await mutate(store=>{new AccountingService(store,store.state.device).execute(ids.map(id=>({action:'PATCH_FIELD',entity:{type:'transactions',id,fields:{purged_at:new Date().toISOString()}}})));});await refresh();trash();});});}
function budgetDialog(){modal('月消费预算',`<form id="budget-form"><label>每月预算 · 元<input name="budget" type="number" min="0.01" step="0.01" value="${state.settings.budget===null?'':state.settings.budget/100}" required></label><p class="footnote">只设置一份月预算；其他期间按每月实际天数折算日额度，再合计所选日期。退款在发生时冲减消费。月预算随账本加密同步。</p><div class="modal-actions"><button type="button" class="secondary" data-action="disable-budget">不设预算</button><button type="submit" class="primary">保存预算</button></div></form>`);$('#budget-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await settings({budget:money(formData(e.target as HTMLFormElement).budget)});await refresh();close();});};}
function batchCategory(){
 const context=batchCategoryContext(snap,filteredBills().filter(t=>selected.has(t.id)).map(t=>t.id));
 if(!context.eligibleIds.length)throw Error('CATEGORY_EDIT_UNAVAILABLE');
 modal('批量修改分类',`<form id="batch-form"><p>选中 ${context.transactionIds.length} 笔，修改其中 ${context.eligibleIds.length} 笔的分类。已关联退款跟随原消费分类；收入等无消费分类的账单不修改。</p><ul>${context.targets.filter(t=>context.eligibleIds.includes(t.id)).map(t=>`<li>${esc(t.fields.display_name)}</li>`).join('')}</ul><label>分类<select name="category">${opts(state.settings.categories.map((c:string)=>[c,c]),'')}</select></label><div class="modal-actions"><button type="submit" class="primary">保存分类</button></div></form>`);
 $('#batch-form').onsubmit=ev=>{ev.preventDefault();submit(ev.target as HTMLFormElement,async()=>{await saveBatchCategory({transactionIds:context.transactionIds,expectedSnapshot:context.expectedSnapshot,category:formData(ev.target as HTMLFormElement).category});selected.clear();await refresh();close();});};
}
function bind(id:string){modal('补认资金账户',`<form id="bind-form"><label>账户<select name="account" required>${accountOpts('',false)}</select></label><p class="footnote">只补充资金实际进出的账户，不改变原始凭证与消费金额。</p><div class="modal-actions"><button type="submit" class="primary">确认账户</button></div></form>`);$('#bind-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{await business({kind:'BIND_ACCOUNT',movementId:id,accountId:formData(e.target as HTMLFormElement).account});await refresh();close();});};}
function meaning(id:string){modal('调整转账的消费用途',`<form id="meaning-form"><p>资金已转出。请明确其中有多少属于真实消费，其余资金不自动认定为消费。</p><label>计入消费 · 元<input name="amount" inputmode="decimal" value="${Number(effect(id)?.fields.amount||0)/100}" required></label><label>分类<select name="category">${opts(state.settings.categories.map((c:string)=>[c,c]),category(id))}</select></label><div class="modal-actions"><button type="submit" class="primary">保存用途</button></div></form>`);$('#meaning-form').onsubmit=e=>{e.preventDefault();submit(e.target as HTMLFormElement,async()=>{const v=formData(e.target as HTMLFormElement);await business({kind:'SET_CONSUMPTION',transactionId:id,amount:Number(v.amount)===0?0:money(v.amount),categoryId:v.category});await refresh();close();});};}
async function demo(){if(state.ops.length)throw Error('演示仅能在空账本中开启');await mutate(store=>{const svc=new BusinessAccountingService(store,store.state.device);const [y,m]=month.split('-').map(Number);const opening=new Date(y,m-1,1,0,0,0).toISOString();for(const [id,name,b] of [['demo-bank','日常银行卡',800000],['demo-wechat','微信余额',125000],['demo-alipay','支付宝余额',50000]] as const)svc.execute({kind:'CREATE_ACCOUNT',id,name,accountType:'ASSET',openingBalance:b,openingBalanceAt:opening});const sample=[['巷口咖啡',2800,'餐饮'],['地铁出行',500,'交通'],['周末的鲜花',4500,'生活'],['午餐 · 好好吃饭',3200,'餐饮'],['一本新书',6800,'学习'],['超市采购',12650,'生活'],['朋友小聚',16800,'餐饮'],['日用品补充',8900,'购物'],['电影之夜',4200,'娱乐'],['早餐',1200,'餐饮']];sample.forEach(([name,amount,cat],i)=>svc.execute({kind:'PURCHASE',id:'demo-'+i,name:String(name),amount:Number(amount),occurredAt:new Date(y,m-1,Math.min(i*2+1,new Date(y,m,0).getDate()),12,0).toISOString(),payer:i%2?'demo-bank':'demo-wechat',categoryId:String(cat),note:'虚构示例，用于体验页面'}));store.state.settings.demo=true;store.state.settings.budget=300000;});await refresh();toast('已开启演示账本');}
const actions:Record<string,()=>any>={new:()=>newRecord(),period:periodDialog,'cloud-login':cloudLoginDialog,'cloud-logout':cloudLogout,'cloud-sync':async()=>{await synchronizeCloud();await refresh();toast('账本已同步');},'cloud-key-backup':async()=>{const current=await read();if(!current.cloud)throw Error('CLOUD_SIGNIN_REQUIRED');download('star-ledger-recovery.json',JSON.stringify({format:'star-ledger-cloud-recovery',version:1,uid:current.cloud.uid,ledger:current.cloud.ledger,recoveryKey:current.cloud.recoveryKey},null,2));},account:()=>accountDialog(),capture, 'import-file':importFile, budget:budgetDialog,trash,demo,'clear-demo':()=>confirmAction('结束演示','演示交易将被清空，然后开始你的个人账本。',async()=>{await mutate(store=>{store.state.importWorkspace=undefined;store.state.ops=[];store.state.pending=[];store.state.batches=[];store.state.envelopes={};store.state.settings.demo=false;store.state.imports=[];store.state.importRevision=(store.state.importRevision||0)+1;});},'开始我的账本'),
'reset-ledger':()=>{if(localCloudIdentity())throw Error('云账本不能在本机重置，请到账单中删除记录');return confirmAction('重置账本','将清空所有账务、导入队列、账户关系记忆与同步绑定，恢复到一个全新的空账本。此操作不可撤销，建议先导出备份。已登录的云账本请通过账单删除功能管理。',async()=>{await mutate(store=>{store.state.importWorkspace=undefined;store.state.ops=[];store.state.pending=[];store.state.batches=[];store.state.envelopes={};store.state.imports=[];store.state.importRevision=(store.state.importRevision||0)+1;store.state.settings={...store.state.settings,demo:false,syncTarget:undefined,syncConfig:undefined,lastSync:undefined};});},'确认重置');},
'forget-all-aliases':()=>forgetMemoryDialog('ALL'),
'clear-import-queue':()=>confirmAction('清除未完成记录','清除未完成的输入，已保存账单保留。',async()=>{await mutate(store=>{store.state.imports=[];store.state.importRevision=(store.state.importRevision||0)+1;});},'确认清空'),'select-all':()=>{const list=filteredBills();selected=selected.size===list.length?new Set():new Set(list.map(t=>t.id));render();},deselect:()=>{selected.clear();render();},'batch-category':batchCategory,'batch-delete':()=>lifecycleDialog('DELETE',filteredBills().filter(t=>selected.has(t.id)).map(t=>t.id)),backup:async()=>download('star-ledger-'+new Date().toISOString().slice(0,10)+'.json',await backup()),restore:async()=>{const file=await chooseFile('.json');if(!file)return;if(file.size>30*1024*1024)throw Error('备份文件过大');const text=await file.text();confirmAction('合并恢复备份','会将备份中的账务记录合并到本机，重复操作会跳过。',async()=>{await restore(text);toast('备份已合并');},'合并恢复');},persist:async()=>toast(await navigator.storage?.persist?.()?'已获准持久存储，仍建议定期备份':'浏览器未授予持久存储，请定期导出备份'),'disable-budget':async()=>{await settings({budget:null});await refresh();close();toast('已关闭预算');},'save-budget':async()=>{await settings({budget:money($<HTMLInputElement>('#budget-input').value)});await refresh();toast('预算已保存');},'add-category':async()=>{const name=$<HTMLInputElement>('#category-name').value.trim();if(!name)return;if(state.settings.categories.includes(name))throw Error('分类已存在');await settings({categories:[...state.settings.categories,name]});await refresh();},'export-csv':()=>{const q=(s:any)=>'"'+String(s??'').replace(/"/g,'""').replace(/^([=+@-])/,'\t$1')+'"';const rows=[['时间','名称','类型','状态','金额元','分类','账户','备注'],...filteredBills().map(t=>[new Date(String(t.fields.occurred_at)).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),t.fields.display_name,typeNames[String(t.fields.event_type)],statusNames[String(t.fields.status)],Number(t.fields.display_amount)/100,category(t.id),accountLabel(t),t.fields.note])];download('star-ledger-'+selectedPeriod().start+'-'+selectedPeriod().end+'.csv','\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'text/csv;charset=utf-8');},help:()=>modal('使用帮助',`<ol class="steps"><li><b>导入并设置账户</b><span>导入账单，按渠道新建或绑定已有账户，名称可改，余额以后再补。</span></li><li><b>记下日常消费</b><span>手机从「概览 → 截图记账」选择图片，核对后保存；也能随时手动记一笔。</span></li><li><b>电脑整理账单</b><span>导入微信 / 支付宝 XLSX 或 CSV，自动识别账户、亲情卡和分类；退款先记录，少数关联稍后整理。</span></li><li><b>连接另一台设备</b><span>在设置中登录同一个云账户。账本本地保存，联网自动同步；换设备后使用同一账户恢复云账本。</span></li><li><b>定期备份</b><span>导出 JSON 备份。清理浏览器网站数据会删除本机记录。截图识别首次需要网络，网页加载完成后基本记账支持离线。</span></li></ol><h3>账户和消费</h3><p>余额由期初余额及其后的资金流水计算；本人账户互转、信用账户还款不重复计消费。亲情卡代付计入本人消费，不扣本人账户。</p><h3>来源保存</h3><p>文件保留逐行原始字段；截图保留识别文字、图片指纹和提取字段。原文件及原图片不存档。</p>`,true)};
document.addEventListener('click',async ev=>{const el=(ev.target as Element).closest<HTMLElement>('button,a[data-page]');if(!el)return;try{if(el.hasAttribute('data-close')){close();return;}const d=el.dataset;if(d.discardEditDraft){if(confirm('放弃这份未保存的修改？')){discardDetailDraft(state.device,d.discardEditDraft);close();}return;}if(d.editDraft){detail(d.transaction!,d.editDraft);return;}if(d.v2Resume){(el as HTMLButtonElement).disabled=true;try{await resumeImportSession(d.v2Resume);await refresh();toast('已恢复处理，请查看导入结果');}finally{(el as HTMLButtonElement).disabled=false;}return;}if(d.v2Attention){await importAttentionDialog(d.session!,d.v2Attention);return;}if(d.page){close();setPage(d.page);return;}if(d.action){if(app.inert)return;app.inert=true;app.setAttribute('aria-busy','true');try{await actions[d.action]?.();}finally{app.inert=false;app.removeAttribute('aria-busy');}return;}if(d.forgetAlias){forgetMemoryDialog([d.forgetAlias]);return;}if(d.linkReturn){linkReturnDialog(d.linkReturn);return;}if(d.detail){detail(d.detail);return;}if(d.account){accountDialog(d.account);return;}if(d.draft!==undefined){newRecord(drafts[Number(d.draft)],Number(d.draft));return;}if(d.refund){refund(d.refund);return;}if(d.delete){lifecycleDialog('DELETE',[d.delete]);return;}if(d.restore){lifecycleDialog('RESTORE',[d.restore]);return;}if(d.restoreAll){lifecycleDialog('RESTORE',entities('transactions').filter(t=>t.fields.deleted_at&&!t.fields.purged_at).map(t=>t.id));return;}
if(d.purge){purgeTransaction(d.purge);return;}
if(d.purgeAll){purgeAllTransactions();return;}if(d.bind){bind(d.bind);return;}if(d.meaning){meaning(d.meaning);return;}if(d.settle){const t=getT(d.settle);newRecord({kind:String(t.fields.event_type),name:String(t.fields.display_name),amount:String(Number(t.fields.display_amount)/100),date:localDate(new Date(String(t.fields.occurred_at))),status:'SUCCESS',account:'',to:'',category:'其他',original:'',note:String(t.fields.note),sponsor:false,consumption:'0'} as Draft,undefined,t);return;}if(d.fail){await business({kind:'SET_STATUS',transactionId:d.fail,status:'FAILED'});await refresh();close();return;}if(d.resolve){const [i,j]=d.resolve.split(':').map(Number),c=snap.conflicts[i];await raw([{action:'RESOLVE_CONFLICT',entity:{type:c.entity_type,id:c.entity_id,fields:{[c.field]:c.candidates[j].value}}}]);await refresh();toast('冲突已解决');return;}if(d.trend){const value=consumptionTrend(snap,selectedPeriod()).find(r=>r.key===d.trend);toast(`${d.trend} · 净消费 ¥${moneyText(value?.amount??null)}`);return;}if(d.day){const amount=activeMonth().filter(t=>dayOf(new Date(String(t.fields.occurred_at)))===Number(d.day)).reduce((sum,t)=>sum+Number(effect(t.id)?.fields.amount||0),0);toast(`${month}-${d.day} · 净消费 ¥${moneyText(snap.conflicts.length?null:amount)}`);}}catch(e){error(e);}});
document.addEventListener('change',async ev=>{const el=ev.target as HTMLInputElement;try{if(el.id==='month'&&el.value){selectPeriod('MONTH',el.value+'-01');month=el.value;rangeMode='MONTH';rangeAnchor=month+'-01';selected.clear();render();}if(el.id==='type-filter'){typeFilter=el.value;selected.clear();render();}if(el.id==='account-filter'){accountFilter=el.value;selected.clear();render();}if(el.id==='status-filter'){statusFilter=el.value;selected.clear();render();}if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);render();}if(el.id==='display-mode'){await settings({mode:el.value});await refresh();}}catch(e){error(e);}});
let searchTimer:ReturnType<typeof setTimeout>;document.addEventListener('input',ev=>{const el=ev.target as HTMLInputElement;if(el.id==='search'){query=el.value;selected.clear();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=el.selectionStart;render();const input=$<HTMLInputElement>('#search');input.focus();input.setSelectionRange(pos,pos);},250);}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';selected.clear();render();});window.addEventListener('online',()=>{if(state)render();});window.addEventListener('offline',()=>{if(state)render();});window.addEventListener('focus',()=>{if(state&&!dialog.open)refresh().catch(error);});
(async()=>{try{await openStore(localCloudIdentity()?.uid??null);const view=new URLSearchParams(location.search).get('view');if(view==='mobile'||view==='desktop'||view==='auto')await settings({mode:view});await refresh();startCloudSync(status=>{const el=$('#cloud-sync-status');if(el)el.textContent=status;if(status==='已同步'&&!dialog.open)refresh().catch(error);});if('serviceWorker'in navigator&&import.meta.env.PROD){const registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});const hint=()=>{if(registration.waiting){toast('发现新版本。待办已保存，请关闭所有星账页面后重新打开。');}};hint();registration.addEventListener('updatefound',()=>registration.installing?.addEventListener('statechange',hint));}}catch(e){app.innerHTML='<div class="startup-error"><h1>暂时无法打开本地账本</h1><p>请关闭其他星账页面后重试，并允许网站存储。</p><button onclick="location.reload()">重试</button></div>';error(e);}})();

window.addEventListener('resize',()=>{if(state){const mode=state.settings.mode||'auto';document.documentElement.dataset.layout=mode==='auto'?(window.innerWidth<=800?'mobile':'desktop'):mode;}});
function linkReturnDialog(id:string){
 const context=refundRelationContext(snap,id),t=context.refund;const suggested=context.candidates.filter(o=>o.id===context.originalId||context.suggested.some(c=>c.id===o.id));
 modal('退款关联',`<form id="link-return-form"><p>${esc(t.fields.display_name)} · ¥ ${moneyText(Number(t.fields.display_amount))}</p><label>原消费 / 转出<select name="original"><option value="">暂不关联 / 解除关联</option>${opts(suggested.map(o=>[o.id,`${o.fields.display_name} · ¥ ${moneyText(Number(o.fields.display_amount))} · ${formatTime(o.fields.occurred_at)}`]),context.originalId||'')}</select></label>${suggested.length?'':'<p>没有找到明确的原账单，退款到账已保留。可以暂不关联，或查找其他账单。</p>'}${context.candidates.length>suggested.length?'<label class="check-label"><input type="checkbox" id="refund-show-all">查找其他账单</label>':''}<label id="return-allocation-field" hidden>这次退回中，多少元是退回已计入的消费？<input name="consumptionReduction" inputmode="decimal" placeholder="请按实际情况填写"><small id="return-allocation-hint"></small></label><p class="footnote">关联只调整退款关系与消费分类，已记录的到账不会再记一遍。</p><div class="modal-actions"><button type="button" class="secondary" data-close>取消</button><button type="submit" class="primary">保存关联</button></div></form>`);
 const form=$<HTMLFormElement>('#link-return-form');const updateAllocation=()=>{const id=formData(form).original,a=context.allocations[id],field=$('#return-allocation-field'),input=form.querySelector<HTMLInputElement>('[name=consumptionReduction]')!;field.hidden=!a?.requiresAnswer;input.required=!!a?.requiresAnswer;if(a){$('#return-allocation-hint').textContent=`原账单 ${moneyText(a.originalAmount)} 元，其中消费 ${moneyText(a.originalConsumption)} 元；本次可减少消费 ${moneyText(a.minimum)} 至 ${moneyText(a.maximum)} 元。`;input.value=context.originalId===id&&context.currentReduction!==undefined?String(context.currentReduction/100):'';}else input.value='';};const showAll=form.querySelector<HTMLInputElement>('#refund-show-all');if(showAll)showAll.onchange=()=>{const select=form.querySelector<HTMLSelectElement>('[name=original]')!,current=select.value;select.innerHTML='<option value="">暂不关联 / 解除关联</option>'+opts((showAll.checked?context.candidates:suggested).map(o=>[o.id,`${o.fields.display_name} · ¥ ${moneyText(Number(o.fields.display_amount))} · ${formatTime(o.fields.occurred_at)}`]),current);updateAllocation();};form.querySelector<HTMLSelectElement>('[name=original]')!.onchange=updateAllocation;updateAllocation();form.onsubmit=e=>{e.preventDefault();submit(form,async()=>{await saveRefundRelation({transactionId:id,originalId:formData(form).original||null,consumptionReduction:$('#return-allocation-field').hidden?undefined:money(formData(form).consumptionReduction,true),expectedSnapshot:context.expectedSnapshot,now:new Date().toISOString()});await refresh();close();toast('退款关联已更新');});};
}

window.addEventListener('storage',event=>{if(event.key===cloudIdentityStorageKey)location.reload();});
